METRICS = [45, 75, 82, 90, 65, 25, 20, 15]
MIN_INSTANCES, MAX_INSTANCES = 2, 5

def step(instances, cpu):
    if cpu > 70:
        return 'out', min(instances + 1, MAX_INSTANCES)
    if cpu < 30:
        return 'in', max(instances - 1, MIN_INSTANCES)
    return 'hold', instances

instances = 2
for cpu in METRICS:
    action, instances = step(instances, cpu)
    print(f'cpu={cpu} action={action} instances={instances}')
print(f'final={instances}')
